/**
 * 负责恶魔猎手的纯事件、自身历史和工具数据契约，保留原政策、可空字段及历史限额。
 * 输入为机器事件名称与已确认 inert 载荷；输出为原脱离事实、状态／工具数据或 null。
 * 公共声明唯一拥有数据形状，原可写性不加强；选择知识不含原体、租约或库存写句柄，
 * 数据合法不授予请求、生命或资源权限。实际状态、提交与封存仍归后端机制。
 * 本浏览器兼容 reader 不保证恶意 Proxy 零 trap；Node 入口须先拒绝，再调用原纯读取。
 */
import { copyEventData } from "../inert-event-data";
export const DEMON_HUNTER_POLICY = "awa_netease_demon_hunter_v1" as const;
export const DEMON_HUNTER_EVENT_TYPES = [
  "demon_hunter_chosen",
  "demon_hunter_cancelled",
  "demon_hunter_poison_immune",
] as const;
export interface DemonHunterChoiceFact {
  policy: typeof DEMON_HUNTER_POLICY;
  actorId: number;
  day: number;
  targetId: number | null;
}
export interface DemonHunterPlayerFact {
  policy: typeof DEMON_HUNTER_POLICY;
  day: number;
  targetId: number | null;
}
export interface DemonHunterCancelFact {
  policy: typeof DEMON_HUNTER_POLICY;
  actorId: number;
  day: number;
  targetId: number;
  reason: "authority_revoked";
  faultId: string | null;
}
export interface DemonHunterPoisonImmuneFact {
  policy: typeof DEMON_HUNTER_POLICY;
  actorId: number;
  day: number;
  witchId: number;
}
export type DemonHunterEventFact =
  DemonHunterChoiceFact | DemonHunterCancelFact | DemonHunterPoisonImmuneFact;
function keys(p: Record<string, unknown>, names: readonly string[]): boolean {
  return Object.keys(p).length === names.length && names.every((key) => Object.hasOwn(p, key));
}
function positive(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0;
}
function data(payload: unknown): Record<string, unknown> | null {
  try {
    const p = copyEventData(payload);
    return p && typeof p === "object" && !Array.isArray(p) ? (p as Record<string, unknown>) : null;
  } catch {
    return null;
  }
}
export function readDemonHunterEventFact(
  type: string,
  payload: unknown,
): DemonHunterEventFact | null {
  const p = data(payload);
  if (!p || p.policy !== DEMON_HUNTER_POLICY || !positive(p.actorId) || !positive(p.day))
    return null;
  if (type === "demon_hunter_poison_immune")
    return keys(p, ["policy", "actorId", "day", "witchId"]) &&
      positive(p.witchId) &&
      p.witchId !== p.actorId
      ? (p as unknown as DemonHunterPoisonImmuneFact)
      : null;
  if ((p.day as number) < 2) return null;
  if (type === "demon_hunter_chosen")
    return keys(p, ["policy", "actorId", "day", "targetId"]) &&
      (p.targetId === null || (positive(p.targetId) && p.targetId !== p.actorId))
      ? (p as unknown as DemonHunterChoiceFact)
      : null;
  if (type === "demon_hunter_cancelled")
    return keys(p, ["policy", "actorId", "day", "targetId", "reason", "faultId"]) &&
      positive(p.targetId) &&
      p.targetId !== p.actorId &&
      p.reason === "authority_revoked" &&
      (p.faultId === null ||
        (typeof p.faultId === "string" && p.faultId.length > 0 && p.faultId.length <= 128))
      ? (p as unknown as DemonHunterCancelFact)
      : null;
  return null;
}
/** 仅玩家自身选择；不含来源、免疫结果、撤销原因、行动者身份或目标阵营。 */
export function readDemonHunterPlayerFact(
  type: string,
  payload: unknown,
): DemonHunterPlayerFact | null {
  const p = data(payload);
  return type === "demon_hunter_chosen" &&
    !!p &&
    keys(p, ["policy", "day", "targetId"]) &&
    p.policy === DEMON_HUNTER_POLICY &&
    positive(p.day) &&
    p.day >= 2 &&
    (p.targetId === null || positive(p.targetId))
    ? (p as unknown as DemonHunterPlayerFact)
    : null;
}

/** 保留原可写选择行；它只描述已记录知识，不授予目标资格、原生命或请求许可。 */
export interface DemonHunterChoice {
  day: number;
  targetId: number | null;
}
export interface DemonHunterState {
  policy: typeof DEMON_HUNTER_POLICY;
  history: DemonHunterChoice[];
}
export interface DemonHuntTool {
  name: "demon_hunt";
  args: { target_id: number | null; abstain: boolean };
}
export function readDemonHunterState(value: unknown): DemonHunterState | null {
  const p = data(value);
  if (
    !p ||
    !keys(p, ["policy", "history"]) ||
    p.policy !== DEMON_HUNTER_POLICY ||
    !Array.isArray(p.history)
  )
    return null;
  let previous = 1;
  for (const row of p.history) {
    if (
      !row ||
      typeof row !== "object" ||
      Array.isArray(row) ||
      !keys(row, ["day", "targetId"]) ||
      !positive(row.day) ||
      row.day <= previous ||
      (row.targetId !== null && !positive(row.targetId))
    )
      return null;
    previous = row.day;
  }
  return p as unknown as DemonHunterState;
}
export function readDemonHuntTool(value: unknown): DemonHuntTool | null {
  const p = data(value);
  if (
    !p ||
    !keys(p, ["name", "args"]) ||
    p.name !== "demon_hunt" ||
    !p.args ||
    typeof p.args !== "object" ||
    Array.isArray(p.args)
  )
    return null;
  const args = p.args as Record<string, unknown>;
  return keys(args, ["target_id", "abstain"]) &&
    (args.target_id === null
      ? args.abstain === true
      : positive(args.target_id) && args.abstain === false)
    ? (p as unknown as DemonHuntTool)
    : null;
}

/**
 * 负责构造恶魔猎手数据并读取原角色的 demonHunter 状态槽，结构包含 policy 和选择 history。
 * 状态库存由原角色及 authority 所有者持有；输入为角色记录或未知工具数据，输出为原字段
 * 校验后的槽引用／工具副本。Node 快照拒绝外来 descriptor，复制只用于校验，查询不生成
 * 第二份 live 状态，也不结算选择或封存资源。公共数据结构归契约包，原字段可写性
 * 不授予生命、请求或资源权限；Node 状态读取和 authority 的许可检查仍各归原所有者。
 */
import { snapshotPlainData } from "../../../../core/domain/plain_data";
import { types } from "node:util";
import type { RoleComponent } from "../../../../core";
import { DEMON_HUNTER_POLICY, readDemonHunterState as readState, readDemonHuntTool as readTool } from "@ai-werewolf-arena/game-contract/facts/demon-hunter";
import type { DemonHunterState, DemonHuntTool } from "@ai-werewolf-arena/game-contract/facts/demon-hunter";
export { DEMON_HUNTER_POLICY };
export const DEMON_HUNTER_ROLE = "demon_hunter" as const;
export function ownDemonData(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const descriptor = Object.getOwnPropertyDescriptor(value, key);
  return descriptor && "value" in descriptor ? descriptor.value : undefined;
}
export function demonSnapshot(
  value: unknown,
  seen = new Set<object>(),
  depth = 0,
  arrayLimit = 256,
): unknown {
  return snapshotPlainData(value, seen, depth, arrayLimit, "demon_hunter_data_invalid");
}
export function demonJson(value: unknown): string | null {
  try {
    return JSON.stringify(demonSnapshot(value));
  } catch {
    return null;
  }
}
export function exactDemonData(
  value: unknown,
  keys: readonly string[],
): value is Record<string, unknown> {
  return (
    !!value &&
    typeof value === "object" &&
    !Array.isArray(value) &&
    Object.keys(value).length === keys.length &&
    keys.every((key) => Object.hasOwn(value, key))
  );
}
export function freshDemonHunterState(): DemonHunterState {
  return { policy: DEMON_HUNTER_POLICY, history: [] };
}
export function readDemonHunterState(value: unknown): DemonHunterState | null {
  try {
    return readState(demonSnapshot(value));
  } catch {
    return null;
  }
}
export function getDemonHunterState(role: RoleComponent | undefined): DemonHunterState | undefined {
  const s = ownDemonData(ownDemonData(role, "privateState"), "demonHunter");
  // 复制只用于验证；成功后仍返回原 slot，不能让查询生成第二份 live 状态。
  return readDemonHunterState(s) ? (s as DemonHunterState) : undefined;
}
export function readDemonHuntTool(value: unknown): DemonHuntTool | null {
  try {
    return readTool(demonSnapshot(value));
  } catch {
    return null;
  }
}

/**
 * 单元编译测试验证恶魔猎手三份公共纯结构的原形状和旧后端类型出口退休。
 * 输入为固定 Git 的独立完整字段预期及 canonical 类型；输出由编译器核对精确形状、
 * 双向赋值、nullable 和原可写性。本单元拥有独立字面 oracle，不运行状态读取、
 * World、权威、模型或提交；数据结构不授予请求、生命或库存权限。
 */
import type {
  DemonHunterChoice,
  DemonHunterState,
  DemonHuntTool,
} from "@ai-werewolf-arena/game-contract/facts/demon-hunter";
import type { PlayerObservation } from "../../../src/game/observation/player-observation";

// @ts-expect-error 旧声明出口退休，不由运行状态叶继续转发纯数据。
import type { DemonHunterChoice as RetiredChoice } from "../../../src/game/mechanisms/roles/demon_hunter/state";
// @ts-expect-error 重复结构退出后端叶，共享事实契约成为唯一 owner。
import type { DemonHunterState as RetiredState } from "../../../src/game/mechanisms/roles/demon_hunter/state";
// @ts-expect-error 重复工具结构退出后端叶，运行 reader 仍保留原出口。
import type { DemonHuntTool as RetiredTool } from "../../../src/game/mechanisms/roles/demon_hunter/state";

interface OriginalChoice {
  day: number;
  targetId: number | null;
}
interface OriginalState {
  policy: "awa_netease_demon_hunter_v1";
  history: OriginalChoice[];
}
interface OriginalTool {
  name: "demon_hunt";
  args: { target_id: number | null; abstain: boolean };
}
type Equal<A, B> =
  (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
type Expect<T extends true> = T;
export type AllDataBoundaryChecks = [
  Expect<Equal<OriginalChoice, DemonHunterChoice>>,
  Expect<Equal<OriginalState, DemonHunterState>>,
  Expect<Equal<OriginalTool, DemonHuntTool>>,
  Expect<Equal<NonNullable<PlayerObservation["ownState"]["demonHunter"]>, OriginalState>>,
  Expect<OriginalChoice extends DemonHunterChoice ? true : false>,
  Expect<DemonHunterChoice extends OriginalChoice ? true : false>,
  Expect<OriginalState extends DemonHunterState ? true : false>,
  Expect<DemonHunterState extends OriginalState ? true : false>,
  Expect<OriginalTool extends DemonHuntTool ? true : false>,
  Expect<DemonHuntTool extends OriginalTool ? true : false>,
  RetiredChoice,
  RetiredState,
  RetiredTool,
];

/** 只编译、不调用：公共原字段仍可写；非法私态、目标真值及权威句柄不进入形状。 */
export function checkOriginalDataMutability(
  choice: DemonHunterChoice,
  state: DemonHunterState,
  tool: DemonHuntTool,
): void {
  choice.day = 2;
  choice.targetId = null;
  state.policy = "awa_netease_demon_hunter_v1";
  state.history.push({ day: 3, targetId: null });
  state.history[0]!.targetId = 4;
  tool.name = "demon_hunt";
  tool.args.target_id = null;
  tool.args.abstain = true;
  // @ts-expect-error 原历史行不携带目标的真实阵营。
  choice.camp;
  // @ts-expect-error 结构不把内部原体或资源权威泄漏给观察消费者。
  state.world;
  // @ts-expect-error 合法工具形状不是已绑定请求租约。
  tool.lease;
}
